if--><!--each story_paras--><p data-reveal>{{.}}</p><!--/each--><!--if editable--></span><!--/if--></div>\n    </div>\n  </div>\n</section>","functions":"<section class=\"vr-details vr-section\" data-tpl-section=\"details\" data-section=\"functions\">\n  <div class=\"vr-wrap\">\n    <div class=\"vr-heading\" data-reveal>\n      <svg class=\"vr-divider\" viewBox=\"0 0 120 12\" aria-hidden=\"true\"><path d=\"M2 6h46M72 6h46\"/><path d=\"M60 1 65 6 60 11 55 6Z\"/></svg>\n      <h2 class=\"vr-title\">{{edit:copy:details_title}}</h2>\n      <!--if venue--><p class=\"vr-lead\">{{edit:venue}}<!--if place-->, {{edit:place}}<!--/if--></p><!--/if-->\n    </div>\n    <div class=\"vr-event-grid\">\n      <!--each events--><article class=\"vr-event-card\" data-reveal>\n        <span class=\"vr-icon\" aria-hidden=\"true\">{{icon:sparkle}}</span>\n        <h3>{{edit:event_title}}</h3>\n        <p class=\"vr-time\"><!--if time_text-->{{time_text}}<!--else-->{{copy:time_unknown}}<!--/if--></p>\n        <!--if date_text--><p class=\"vr-when\">{{date_text}}</p><!--/if-->\n        <!--if venue--><p class=\"vr-venue\">{{edit:event_venue}}</p><!--/if-->\n        <!--if map--><a class=\"vr-link\" href=\"{{map}}\" target=\"_blank\" rel=\"noopener noreferrer\">{{upper:copy:directions}}<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M7 17 17 7M8.5 7H17v8.5\"/></svg></a><!--/if-->\n      {{calendar}}\n      </article><!--/each-->\n    </div><!--if editable--><div data-add-wrap><button type=\"button\" data-add-event aria-expanded=\"false\">+ Add an event</button></div><!--/if-->\n  </div>\n</section>","gallery":"<section class=\"vr-gallery vr-section\" data-tpl-section=\"gallery\" data-section=\"gallery\">\n  <div class=\"vr-wrap\">\n    <div class=\"vr-heading\" data-reveal>\n      <svg class=\"vr-divider\" viewBox=\"0 0 120 12\" aria-hidden=\"true\"><path d=\"M2 6h46M72 6h46\"/><path d=\"M60 1 65 6 60 11 55 6Z\"/></svg>\n      <h2 class=\"vr-title\">{{em:edit:copy:gallery_title}}</